NEW_SOURCE='from __future__ import annotations\nfrom concurrent.futures import ThreadPoolExecutor,as_completed\nfrom dataclasses import dataclass\nimport time\nfrom .oad_148_solana_mainnet_chain_state_acquisition import _rpc\nREAD_ONLY=True; PROBABILITY_ENABLED=False; DIRECTION_ENABLED=False; PUBLICATION_ALLOWED=False; EXECUTION_AUTHORITY=False\n\n@dataclass(frozen=True,slots=True)\nclass SolanaFinalizedBlockBatch:\n    head_slot:int; requested_start:int; finalized_slots:tuple; blocks:tuple; transaction_count:int; execution_authority:bool=False\n\ndef _is_transient_rpc_error(exc):\n    msg=str(exc).lower()\n    code=getattr(exc,"code",None)\n    return code==429 or any(x in msg for x in (\n        "429","too many requests","rate limit","timed out","timeout",\n        "temporarily unavailable","connection reset","remote end closed connection"\n    ))\n\ndef _fetch_block_once(slot,timeout_seconds):\n    return int(slot),_rpc("getBlock",[int(slot),{"commitment":"finalized","encoding":"jsonParsed","transactionDetails":"full","rewards":False,"maxSupportedTransactionVersion":0}],timeout_seconds)\n\ndef _fetch_wave(slots,timeout_seconds,workers):\n    slots=tuple(int(s) for s in slots)\n    workers=max(1,min(int(workers),len(slots))) if slots else 1\n    ok={}; transient={}; hard={}\n    if not slots:return ok,transient,hard\n    if workers==1:\n        for slot in slots:\n            try:\n                s,b=_fetch_block_once(slot,timeout_seconds); ok[s]=b\n            except Exception as exc:\n                (transient if _is_transient_rpc_error(exc) else hard)[slot]=exc\n        return ok,transient,hard\n    with ThreadPoolExecutor(max_workers=workers,thread_name_prefix="oracle-solana-block") as pool:\n        futures={pool.submit(_fetch_block_once,slot,timeout_seconds):slot for slot in slots}\n        for fut in as_completed(futures):\n            slot=futures[fut]\n            try:\n                s,b=fut.result(); ok[s]=b\n            except Exception as exc:\n                (transient if _is_transient_rpc_error(exc) else hard)[slot]=exc\n    return ok,transient,hard\n\ndef _fetch_blocks_adaptive(slots,timeout_seconds,max_workers=4,max_waves=6,sleep_fn=time.sleep):\n    pending=tuple(int(s) for s in slots)\n    collected={}\n    workers=max(1,min(int(max_workers),4,len(pending))) if pending else 1\n    last_transient=None\n    for wave in range(max(1,int(max_waves))):\n        ok,transient,hard=_fetch_wave(pending,timeout_seconds,workers)\n        collected.update(ok)\n        if hard:\n            slot=sorted(hard)[0]; raise hard[slot]\n        pending=tuple(s for s in pending if s not in collected)\n        if not pending:return collected\n        if transient:\n            last_transient=transient[sorted(transient)[0]]\n        if wave+1>=max(1,int(max_waves)):break\n        workers=max(1,workers//2)\n        sleep_fn(min(8.0,0.5*(2**wave)))\n    if pending:\n        if last_transient is not None:raise last_transient\n        raise RuntimeError("Solana finalized block acquisition incomplete")\n    return collected\n\ndef acquire_finalized_block_batch(start_slot=None,limit=4,timeout_seconds=20.0,max_workers=4,max_waves=6,sleep_fn=time.sleep):\n    head=int(_rpc("getSlot",[{"commitment":"finalized"}],timeout_seconds))\n    limit=max(1,min(int(limit),32))\n    start=max(0,int(start_slot) if start_slot is not None else head-limit+1)\n    stop=min(head,start+limit-1)\n    slots=tuple(int(x) for x in (_rpc("getBlocks",[start,stop,{"commitment":"finalized"}],timeout_seconds) or ()))\n    slots=slots[-limit:]\n    if not slots:return SolanaFinalizedBlockBatch(head,start,(),(),0,False)\n    by_slot=_fetch_blocks_adaptive(slots,timeout_seconds,max_workers,max_waves,sleep_fn)\n    blocks=[];txc=0\n    for slot in slots:\n        block=by_slot.get(slot)\n        if not isinstance(block,dict):continue\n        tx=tuple(block.get("transactions") or ());txc+=len(tx);blocks.append((slot,block))\n    return SolanaFinalizedBlockBatch(head,start,slots,tuple(blocks),txc,False)\n'
TEST_SOURCE='import threading,time,unittest\nfrom unittest.mock import patch\nfrom urllib.error import HTTPError\nfrom qseries_v2.oracle_adapters.independent import oad_318_solana_native_finalized_block_stream as m\n\nclass T(unittest.TestCase):\n    def test_parallel_success_preserves_order(self):\n        lock=threading.Lock();active=0;peak=0\n        def rpc(method,params,timeout):\n            nonlocal active,peak\n            if method=="getSlot":return 200\n            if method=="getBlocks":return list(range(101,109))\n            if method=="getBlock":\n                with lock:active+=1;peak=max(peak,active)\n                time.sleep(.01)\n                with lock:active-=1\n                return {"transactions":[{"slot":params[0]}]}\n            raise AssertionError(method)\n        with patch.object(m,"_rpc",side_effect=rpc):\n            x=m.acquire_finalized_block_batch(101,8,2,max_workers=4,sleep_fn=lambda _:None)\n        self.assertGreater(peak,1)\n        self.assertEqual(tuple(s for s,_ in x.blocks),tuple(range(101,109)))\n\n    def test_429_keeps_successes_and_downshifts_only_missing(self):\n        calls={}; sleeps=[]\n        def rpc(method,params,timeout):\n            if method=="getSlot":return 200\n            if method=="getBlocks":return [101,102,103,104]\n            if method=="getBlock":\n                slot=params[0];calls[slot]=calls.get(slot,0)+1\n                if slot in (103,104) and calls[slot]==1:\n                    raise HTTPError("https://api.mainnet-beta.solana.com",429,"Too Many Requests",None,None)\n                return {"transactions":[{"slot":slot}]}\n            raise AssertionError(method)\n        with patch.object(m,"_rpc",side_effect=rpc):\n            x=m.acquire_finalized_block_batch(101,4,2,max_workers=4,max_waves=4,sleep_fn=sleeps.append)\n        self.assertEqual(tuple(s for s,_ in x.blocks),(101,102,103,104))\n        self.assertEqual(calls[101],1);self.assertEqual(calls[102],1)\n        self.assertEqual(calls[103],2);self.assertEqual(calls[104],2)\n        self.assertTrue(sleeps)\n\n    def test_persistent_429_downshifts_to_serial_then_recovers(self):\n        calls={};sleeps=[]\n        def rpc(method,params,timeout):\n            if method=="getSlot":return 300\n            if method=="getBlocks":return [201,202]\n            if method=="getBlock":\n                slot=params[0];calls[slot]=calls.get(slot,0)+1\n                if calls[slot] < 3: raise RuntimeError("HTTP 429 Too Many Requests")\n                return {"transactions":[]}\n        with patch.object(m,"_rpc",side_effect=rpc):\n            x=m.acquire_finalized_block_batch(201,2,2,max_workers=4,max_waves=5,sleep_fn=sleeps.append)\n        self.assertEqual(tuple(s for s,_ in x.blocks),(201,202))\n        self.assertGreaterEqual(calls[201],3);self.assertGreaterEqual(calls[202],3)\n        self.assertGreaterEqual(len(sleeps),2)\n\n    def test_hard_error_fails_closed(self):\n        def rpc(method,params,timeout):\n            if method=="getSlot":return 100\n            if method=="getBlocks":return [90]\n            if method=="getBlock":raise ValueError("malformed response")\n        with patch.object(m,"_rpc",side_effect=rpc):\n            with self.assertRaises(ValueError):m.acquire_finalized_block_batch(90,1,2,sleep_fn=lambda _:None)\n\n    def test_limit_stays_32(self):\n        calls=[]\n        def rpc(method,params,timeout):\n            calls.append((method,params))\n            if method=="getSlot":return 100\n            if method=="getBlocks":return []\n        with patch.object(m,"_rpc",side_effect=rpc):m.acquire_finalized_block_batch(1,999,2)\n        gb=[x for x in calls if x[0]=="getBlocks"][0]\n        self.assertEqual(gb[1][1],32)\n\nif __name__=="__main__":\n    rr=unittest.TextTestRunner(verbosity=2).run(unittest.defaultTestLoader.loadTestsFromTestCase(T))\n    if not rr.wasSuccessful():raise SystemExit(1)\n    print("[PASS] OAD-412 public-RPC adaptive acquisition rebuild certified")\n    print("[PASS] 429 waves retain successful blocks and retry only missing slots")\n    print("[PASS] concurrency downshifts 4->2->1 under repeated rate limiting")\n'
